export async function promoteQualifiedProspect(prospectId: string): Promise<{
  leadId: string | null;
  created: boolean;
  blocked: boolean;
  reason: string | null;
}> {
  const supabase = getSupabaseAdmin();
  const { data: prospect } = await supabase
    .from("prospects")
    .select("id, company_id, lead_id, pursue_decision")
    .eq("id", prospectId)
    .maybeSingle();
  if (!prospect) throw new Error("Prospect not found");
  if (prospect.lead_id) {
    return { leadId: prospect.lead_id, created: false, blocked: false, reason: null };
  }
  const engagement = await evaluateAccountEngagement(prospect.company_id);
  const block = shouldBlockNewLead(engagement);
  if (block.blocked) {
    return { leadId: null, created: false, blocked: true, reason: block.reason };
  }
  if (prospect.pursue_decision && prospect.pursue_decision !== "pursue") {
    return {
      leadId: null,
      created: false,
      blocked: true,
      reason: "The prospect cannot be promoted to a Lead until the pursue decision and required evidence are confirmed.",
    };
  }
  const promoted = await promoteProspectToLead(prospectId);
  await persistAccountStatus(
    prospect.company_id,
    engagement.status === "NEW_ACCOUNT" ? "UNCONTACTED" : engagement.status
  );
  return {
    leadId: promoted.leadId,
    created: promoted.created,
    blocked: false,
    reason: null,
  };
}

export async function approveOutreach(prospectId: string, actor = "human"): Promise<{
  ready: boolean;
}> {
  const supabase = getSupabaseAdmin();
  const readiness = await computeOutreachReadiness(prospectId);
  if (!readiness.approvalReady) {
    throw new Error("Research / Contact / Why Now / Message readiness is incomplete.");
  }
  await supabase
    .from("prospects")
    .update({
      outreach_approved_at: new Date().toISOString(),
      outreach_approved_by: actor,
      ready_to_contact: false,
      next_action: "Review the evidence and complete the required outreach readiness checks.",
      updated_at: new Date().toISOString(),
    })
    .eq("id", prospectId);
  return { ready: true };
}

export async function loadNewBusinessWorkspace() {
  const supabase = getSupabaseAdmin();
  const offering = await loadActiveOffering();
  const [
    { data: queue },
    { data: ready },
    { data: signals },
    { data: whyNow },
    { data: assessments },
  ] = await Promise.all([
    supabase
      .from("prospects")
      .select(
        `
        id, status, score, fit_score, intent_score, pursue_decision, target_department, target_role,
        contactability, ready_to_contact, research_ready, contact_ready, why_now_ready, message_ready,
        approval_ready, next_action, lead_id, offering_id, metadata, last_activity_at,
        companies ( id, name, domain, industry, account_status, country, last_researched_at, website_url )
      `
      )
      .order("last_activity_at", { ascending: false, nullsFirst: false })
      .limit(40),
    supabase
      .from("prospects")
      .select("id, ready_to_contact, pursue_decision, companies ( name )")
      .eq("ready_to_contact", true)
      .order("last_activity_at", { ascending: false, nullsFirst: false })
      .limit(20),
    supabase
      .from("intent_signals")
      .select(
        "id, company_id, signal_type, title, fact_text, hypothesis, source, source_url, detected_at, first_seen_at, last_seen_at, expires_at, recency, confidence, evidence"
      )
      .order("detected_at", { ascending: false })
      .limit(30),
    supabase
      .from("why_now_briefs")
      .select(
        "id, company_id, prospect_id, fact_text, source_url, source_name, detected_at, business_change, potential_need, why_now, recommended_action, recommended_contact, confidence, used_ai, created_at"
      )
      .order("created_at", { ascending: false })
      .limit(20),
    supabase
      .from("qualification_assessments")
      .select(
        "id, company_id, prospect_id, icp_fit, intent, timing, recent_change, need_hypothesis, evidence_quality, contactability, why_this_company, decision, created_at"
      )
      .order("created_at", { ascending: false })
      .limit(20),
  ]);

  const counts = {
    pursue: (queue ?? []).filter((row) => row.pursue_decision === "pursue").length,
    watch: (queue ?? []).filter((row) => row.pursue_decision === "watch").length,
    investigate: (queue ?? []).filter((row) => row.pursue_decision === "investigate").length,
    disqualify: (queue ?? []).filter((row) => row.pursue_decision === "disqualify").length,
    readyToContact: (ready ?? []).length,
  };

  return {
    offering,
    counts,
    queue: queue ?? [],
    ready: ready ?? [],
    signals: signals ?? [],
    whyNow: whyNow ?? [],
    assessments: assessments ?? [],
  };
}
